      html: '<button class="btn btn-primary" (click)="open()">Open Wizard</button>\n\n<appfx-wizard\n  title="Create Virtual Machine"\n  [pages]="steps"\n  [wizardModel]="model"\n  [opened]="isOpen"\n  (openedChange)="isOpen = $event"\n  [closeHandler]="closeHandler"\n></appfx-wizard>\n',
